inline const MDP *GetMDP(const void *buf) {
  return ::flatbuffers::GetRoot<MDP>(buf);
}

inline const MDP *GetSizePrefixedMDP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<MDP>(buf);
}

inline const char *MDPIdentifier() {
  return "$MDP";
}

inline bool MDPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, MDPIdentifier());
}

inline bool SizePrefixedMDPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, MDPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyMDPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<MDP>(MDPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedMDPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<MDP>(MDPIdentifier());
}

inline void FinishMDPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<MDP> root) {
  fbb.Finish(root, MDPIdentifier());
}

inline void FinishSizePrefixedMDPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<MDP> root) {
  fbb.FinishSizePrefixed(root, MDPIdentifier());
}

inline std::unique_ptr<MDPT> UnPackMDP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<MDPT>(GetMDP(buf)->UnPack(res));
}

inline std::unique_ptr<MDPT> UnPackSizePrefixedMDP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<MDPT>(GetSizePrefixedMDP(buf)->UnPack(res));
}

